package app

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"

	"github.com/Antonio7098/ultraplan-go/internal/productstate"
	"github.com/Antonio7098/ultraplan-go/internal/project"
	"github.com/Antonio7098/ultraplan-go/internal/runcontrol"
	"github.com/Antonio7098/ultraplan-go/internal/sprint"
	"github.com/Antonio7098/ultraplan-go/internal/study"
)

type storageMigrationItem struct {
	Kind   string `json:"kind"`
	Scope  string `json:"scope"`
	Path   string `json:"path"`
	Status string `json:"status"`
	Error  string `json:"error,omitempty"`
}

type storageMigrationResult struct {
	SchemaVersion int                    `json:"schema_version"`
	DryRun        bool                   `json:"dry_run"`
	Imported      int                    `json:"imported"`
	Skipped       int                    `json:"skipped"`
	Failed        int                    `json:"failed"`
	Items         []storageMigrationItem `json:"items"`
}

func runStorage(deps dependencies, args []string) error {
	if len(args) == 0 || args[0] == "--help" || args[0] == "-h" {
		_, err := deps.stdout.Write([]byte(storageHelp()))
		return err
	}
	if args[0] != "migrate" {
		return classified(ExitUsage, "storage: expected 'migrate'")
	}
	dryRun, jsonOut := false, false
	for _, arg := range args[1:] {
		switch arg {
		case "--dry-run":
			dryRun = true
		case "--json":
			jsonOut = true
		case "--help", "-h":
			_, err := deps.stdout.Write([]byte(storageHelp()))
			return err
		default:
			return classified(ExitUsage, "storage migrate: unknown argument %q", arg)
		}
	}
	root, err := discoverWorkspace(deps)
	if err != nil {
		return err
	}
	if !dryRun {
		repository, err := runcontrol.OpenSQLite(deps.ctx, root.Path, runcontrol.SQLiteOptions{})
		if err != nil {
			return classifiedCause(ExitWorkspace, err, "storage.migrate: open workspace database")
		}
		defer repository.Close()
		if _, err := productstate.Ensure(root.Path); err != nil {
			return classifiedCause(ExitWorkspace, err, "storage.migrate: create product-state schema")
		}
	}
	result := storageMigrationResult{SchemaVersion: 1, DryRun: dryRun, Items: []storageMigrationItem{}}
	appendItem := func(item storageMigrationItem) {
		result.Items = append(result.Items, item)
		switch item.Status {
		case "imported", "would_import":
			result.Imported++
		case "skipped":
			result.Skipped++
		case "failed":
			result.Failed++
		}
	}
	studies, err := study.DiscoverStudies(root.Path)
	if err != nil {
		return classifiedCause(ExitWorkspace, err, "storage.migrate: discover studies")
	}
	for _, item := range studies {
		path := study.RunStatePath(item)
		if _, err := os.Stat(path); err != nil {
			if !os.IsNotExist(err) {
				appendItem(storageMigrationItem{Kind: "study_run", Scope: item.Name, Path: path, Status: "failed", Error: err.Error()})
			}
			continue
		}
		stored, err := study.RunStateInDatabase(item)
		if err != nil {
			appendItem(storageMigrationItem{Kind: "study_run", Scope: item.Name, Path: path, Status: "failed", Error: err.Error()})
			continue
		}
		if stored {
			appendItem(storageMigrationItem{Kind: "study_run", Scope: item.Name, Path: path, Status: "skipped"})
			continue
		}
		state, err := study.LoadRunState(item)
		if err == nil && !dryRun {
			err = study.MigrateRunStateToDatabase(item, state)
		}
		appendItem(migrationItem("study_run", item.Name, path, dryRun, err))
	}
	projects, err := project.DiscoverProjects(root.Path)
	if err != nil {
		return classifiedCause(ExitWorkspace, err, "storage.migrate: discover projects")
	}
	for _, projectItem := range projects {
		sprints, err := sprint.DiscoverSprints(root.Path, projectItem)
		if err != nil {
			appendItem(storageMigrationItem{Kind: "project", Scope: projectItem.Name, Path: projectItem.Path, Status: "failed", Error: err.Error()})
			continue
		}
		for _, sprintItem := range sprints {
			migrateSprintState(root.Path, sprintItem, dryRun, appendItem)
		}
	}
	if jsonOut {
		if err := json.NewEncoder(deps.stdout).Encode(result); err != nil {
			return err
		}
	} else {
		for _, item := range result.Items {
			fmt.Fprintf(deps.stdout, "%-12s %-14s %s %s", item.Status, item.Kind, item.Scope, filepath.ToSlash(item.Path))
			if item.Error != "" {
				fmt.Fprintf(deps.stdout, " | %s", item.Error)
			}
			fmt.Fprintln(deps.stdout)
		}
		fmt.Fprintf(deps.stdout, "Product-state migration: %d imported, %d skipped, %d failed\n", result.Imported, result.Skipped, result.Failed)
	}
	if result.Failed > 0 {
		return classified(ExitPartial, "storage.migrate: %d state artifact(s) failed validation or import", result.Failed)
	}
	return nil
}

func migrateSprintState(root string, sp sprint.Sprint, dryRun bool, appendItem func(storageMigrationItem)) {
	scope := sp.Project + "/" + sp.Slug
	flowPath, flowPathErr := sprint.FlowStatePath(root, sp)
	if flowPathErr == nil {
		if _, err := os.Stat(flowPath); err == nil {
			stored, checkErr := sprint.FlowStateInDatabase(root, sp)
			if checkErr != nil {
				appendItem(storageMigrationItem{Kind: "sprint_flow", Scope: scope, Path: flowPath, Status: "failed", Error: checkErr.Error()})
			} else if stored {
				appendItem(storageMigrationItem{Kind: "sprint_flow", Scope: scope, Path: flowPath, Status: "skipped"})
			} else {
				state, loadErr := sprint.LoadFlowState(root, sp)
				if loadErr == nil && !dryRun {
					loadErr = sprint.MigrateFlowStateToDatabase(root, sp, state)
				}
				appendItem(migrationItem("sprint_flow", scope, flowPath, dryRun, loadErr))
			}
		} else if !os.IsNotExist(err) {
			appendItem(storageMigrationItem{Kind: "sprint_flow", Scope: scope, Path: flowPath, Status: "failed", Error: err.Error()})
		}
	}
	executePath, executePathErr := sprint.ExecuteRunStatePath(root, sp)
	if executePathErr == nil {
		if _, err := os.Stat(executePath); err == nil {
			if _, legacy := sprint.LegacyTerminalExecuteStatus(root, sp); legacy {
				appendItem(storageMigrationItem{Kind: "sprint_execute", Scope: scope, Path: executePath, Status: "skipped"})
				return
			}
			stored, checkErr := sprint.ExecuteStateInDatabase(root, sp)
			if checkErr != nil {
				appendItem(storageMigrationItem{Kind: "sprint_execute", Scope: scope, Path: executePath, Status: "failed", Error: checkErr.Error()})
			} else if stored {
				appendItem(storageMigrationItem{Kind: "sprint_execute", Scope: scope, Path: executePath, Status: "skipped"})
			} else {
				state, loadErr := sprint.LoadExecuteRunState(root, sp)
				if loadErr == nil && !dryRun {
					loadErr = sprint.MigrateExecuteStateToDatabase(root, sp, state)
				}
				appendItem(migrationItem("sprint_execute", scope, executePath, dryRun, loadErr))
			}
		} else if !os.IsNotExist(err) {
			appendItem(storageMigrationItem{Kind: "sprint_execute", Scope: scope, Path: executePath, Status: "failed", Error: err.Error()})
		}
	}
}

func migrationItem(kind, scope, path string, dryRun bool, err error) storageMigrationItem {
	if err != nil {
		return storageMigrationItem{Kind: kind, Scope: scope, Path: path, Status: "failed", Error: err.Error()}
	}
	status := "imported"
	if dryRun {
		status = "would_import"
	}
	return storageMigrationItem{Kind: kind, Scope: scope, Path: path, Status: status}
}

func storageHelp() string {
	return `ultraplan storage migrate

Usage:
  ultraplan [--workspace <path>] storage migrate [--dry-run] [--json]

Imports existing study run state, sprint flow state, and sprint execute state
into the workspace SQLite database. Existing files remain as checkpoints.
`
}

package productstate

import (
	"context"
	"crypto/sha256"
	"database/sql"
	"errors"
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"strconv"
	"sync"
	"time"

	_ "modernc.org/sqlite"
)

const DatabaseRelativePath = ".ultraplan/run-control.db"

var ErrNotFound = errors.New("product state not found")

type Item struct {
	Key     string
	Ordinal int
	Payload []byte
}

type Record struct {
	Kind          string
	Scope         string
	SchemaVersion int
	Header        []byte
	Items         []Item
}

type Store struct{ db *sql.DB }

var stores sync.Map

func Existing(root string) (*Store, bool, error) {
	path := filepath.Join(root, filepath.FromSlash(DatabaseRelativePath))
	if _, err := os.Stat(path); err != nil {
		if os.IsNotExist(err) {
			return nil, false, nil
		}
		return nil, false, err
	}
	store, err := open(root)
	return store, err == nil, err
}

func Ensure(root string) (*Store, error) { return open(root) }

func open(root string) (*Store, error) {
	root, err := filepath.Abs(root)
	if err != nil {
		return nil, err
	}
	if cached, ok := stores.Load(root); ok {
		return cached.(*Store), nil
	}
	path := filepath.Join(root, filepath.FromSlash(DatabaseRelativePath))
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return nil, err
	}
	values := url.Values{}
	values.Set("_busy_timeout", strconv.FormatInt((5*time.Second).Milliseconds(), 10))
	values.Set("_foreign_keys", "on")
	values.Set("_journal_mode", "WAL")
	values.Set("_synchronous", "FULL")
	values.Set("_txlock", "immediate")
	dsn := (&url.URL{Scheme: "file", Path: filepath.ToSlash(path), RawQuery: values.Encode()}).String()
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, err
	}
	db.SetMaxOpenConns(4)
	if err := createSchema(context.Background(), db); err != nil {
		_ = db.Close()
		return nil, err
	}
	store := &Store{db: db}
	actual, loaded := stores.LoadOrStore(root, store)
	if loaded {
		_ = db.Close()
		return actual.(*Store), nil
	}
	return store, nil
}

func createSchema(ctx context.Context, db *sql.DB) error {
	_, err := db.ExecContext(ctx, `
CREATE TABLE IF NOT EXISTS product_states (
  kind TEXT NOT NULL,
  scope TEXT NOT NULL,
  schema_version INTEGER NOT NULL,
  header_json BLOB NOT NULL,
  header_hash BLOB NOT NULL,
  updated_at TEXT NOT NULL,
  PRIMARY KEY (kind, scope)
);
CREATE TABLE IF NOT EXISTS product_state_items (
  kind TEXT NOT NULL,
  scope TEXT NOT NULL,
  item_key TEXT NOT NULL,
  ordinal INTEGER NOT NULL,
  payload_json BLOB NOT NULL,
  payload_hash BLOB NOT NULL,
  PRIMARY KEY (kind, scope, item_key),
  FOREIGN KEY (kind, scope) REFERENCES product_states(kind, scope) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS product_state_items_order ON product_state_items(kind, scope, ordinal);
`)
	return err
}

func (s *Store) Has(ctx context.Context, kind, scope string) (bool, error) {
	var found int
	err := s.db.QueryRowContext(ctx, `SELECT 1 FROM product_states WHERE kind = ? AND scope = ?`, kind, scope).Scan(&found)
	if errors.Is(err, sql.ErrNoRows) {
		return false, nil
	}
	return err == nil, err
}

func (s *Store) Load(ctx context.Context, kind, scope string) (Record, error) {
	record := Record{Kind: kind, Scope: scope}
	if err := s.db.QueryRowContext(ctx, `SELECT schema_version, header_json FROM product_states WHERE kind = ? AND scope = ?`, kind, scope).Scan(&record.SchemaVersion, &record.Header); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return Record{}, ErrNotFound
		}
		return Record{}, err
	}
	rows, err := s.db.QueryContext(ctx, `SELECT item_key, ordinal, payload_json FROM product_state_items WHERE kind = ? AND scope = ? ORDER BY ordinal`, kind, scope)
	if err != nil {
		return Record{}, err
	}
	defer rows.Close()
	for rows.Next() {
		var item Item
		if err := rows.Scan(&item.Key, &item.Ordinal, &item.Payload); err != nil {
			return Record{}, err
		}
		record.Items = append(record.Items, item)
	}
	return record, rows.Err()
}

func (s *Store) Save(ctx context.Context, record Record) error {
	if record.Kind == "" || record.Scope == "" || record.SchemaVersion < 1 || len(record.Header) == 0 {
		return errors.New("invalid product state record")
	}
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback()
	headerHash := sha256.Sum256(record.Header)
	if _, err := tx.ExecContext(ctx, `INSERT INTO product_states(kind, scope, schema_version, header_json, header_hash, updated_at)
VALUES(?, ?, ?, ?, ?, ?) ON CONFLICT(kind, scope) DO UPDATE SET schema_version=excluded.schema_version,
header_json=excluded.header_json, header_hash=excluded.header_hash, updated_at=excluded.updated_at
WHERE product_states.header_hash <> excluded.header_hash OR product_states.schema_version <> excluded.schema_version`,
		record.Kind, record.Scope, record.SchemaVersion, record.Header, headerHash[:], time.Now().UTC().Format(time.RFC3339Nano)); err != nil {
		return err
	}
	keep := make(map[string]bool, len(record.Items))
	for _, item := range record.Items {
		if item.Key == "" {
			return fmt.Errorf("product state item key is required")
		}
		keep[item.Key] = true
		hash := sha256.Sum256(item.Payload)
		if _, err := tx.ExecContext(ctx, `INSERT INTO product_state_items(kind, scope, item_key, ordinal, payload_json, payload_hash)
VALUES(?, ?, ?, ?, ?, ?) ON CONFLICT(kind, scope,item_key) DO UPDATE SET ordinal=excluded.ordinal,
payload_json=excluded.payload_json, payload_hash=excluded.payload_hash
WHERE product_state_items.payload_hash <> excluded.payload_hash OR product_state_items.ordinal <> excluded.ordinal`,
			record.Kind, record.Scope, item.Key, item.Ordinal, item.Payload, hash[:]); err != nil {
			return err
		}
	}
	rows, err := tx.QueryContext(ctx, `SELECT item_key FROM product_state_items WHERE kind = ? AND scope = ?`, record.Kind, record.Scope)
	if err != nil {
		return err
	}
	var stale []string
	for rows.Next() {
		var key string
		if err := rows.Scan(&key); err != nil {
			_ = rows.Close()
			return err
		}
		if !keep[key] {
			stale = append(stale, key)
		}
	}
	if err := rows.Close(); err != nil {
		return err
	}
	for _, key := range stale {
		if _, err := tx.ExecContext(ctx, `DELETE FROM product_state_items WHERE kind=? AND scope=? AND item_key=?`, record.Kind, record.Scope, key); err != nil {
			return err
		}
	}
	return tx.Commit()
}

package study

import (
	"context"
	"encoding/json"
	"errors"
	"path/filepath"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/productstate"
)

const studyRunStateKind = "study_run"

func studyWorkspaceRoot(study Study) string { return filepath.Dir(filepath.Dir(study.Path)) }

func loadRunStateDatabase(study Study) (RunState, bool, error) {
	store, enabled, err := productstate.Existing(studyWorkspaceRoot(study))
	if err != nil || !enabled {
		return RunState{}, false, err
	}
	record, err := store.Load(context.Background(), studyRunStateKind, study.Name)
	if errors.Is(err, productstate.ErrNotFound) {
		return RunState{}, false, nil
	}
	if err != nil {
		return RunState{}, false, err
	}
	var state RunState
	if err := json.Unmarshal(record.Header, &state); err != nil {
		return RunState{}, false, err
	}
	for _, item := range record.Items {
		var task TaskState
		if err := json.Unmarshal(item.Payload, &task); err != nil {
			return RunState{}, false, err
		}
		state.Tasks = append(state.Tasks, task)
	}
	return state, true, nil
}

func saveRunStateDatabase(study Study, state RunState) error {
	state.UpdatedAt = time.Now().UTC()
	compactRunStateDiagnostics(&state)
	if err := ValidateRunState(state, RunStatePath(study)); err != nil {
		return err
	}
	header := cloneRunState(state)
	header.Tasks = nil
	headerJSON, err := json.Marshal(header)
	if err != nil {
		return err
	}
	items := make([]productstate.Item, 0, len(state.Tasks))
	for index, task := range state.Tasks {
		payload, err := json.Marshal(task)
		if err != nil {
			return err
		}
		items = append(items, productstate.Item{Key: task.ID, Ordinal: index, Payload: payload})
	}
	store, err := productstate.Ensure(studyWorkspaceRoot(study))
	if err != nil {
		return err
	}
	return store.Save(context.Background(), productstate.Record{Kind: studyRunStateKind, Scope: study.Name, SchemaVersion: state.SchemaVersion, Header: headerJSON, Items: items})
}

func RunStateInDatabase(study Study) (bool, error) {
	store, enabled, err := productstate.Existing(studyWorkspaceRoot(study))
	if err != nil || !enabled {
		return false, err
	}
	return store.Has(context.Background(), studyRunStateKind, study.Name)
}

func MigrateRunStateToDatabase(study Study, state RunState) error {
	return saveRunStateDatabase(study, state)
}

