	case StageExecute:
		return base + "/execute.md"
	case StageReview:
		return base + "/review.md"
	case StageSmoke:
		return base + "/smoke.md"
	default:
		return base
	}
}

func FlowStateRelPath(s Sprint) string {
	return filepath.ToSlash(filepath.Join("projects", s.Project, "sprints", s.Slug, "flow-state.json"))
}

func ExecuteRunStateRelPath(s Sprint) string {
	return filepath.ToSlash(filepath.Join("projects", s.Project, "sprints", s.Slug, ".run-state.json"))
}

func ArtifactPath(root string, s Sprint, stage PlanningStage) (string, error) {
	return resolveSprintContained(root, s, ArtifactRelPath(s, stage))
}

func FlowStatePath(root string, s Sprint) (string, error) {
	return resolveSprintContained(root, s, FlowStateRelPath(s))
}

func resolveSprintContained(root string, s Sprint, rel string) (string, error) {
	if filepath.IsAbs(rel) {
		return "", fmt.Errorf("artifact path %q must be workspace-relative", rel)
	}
	cleanRel := filepath.ToSlash(filepath.Clean(filepath.FromSlash(rel)))
	if cleanRel == "." || strings.HasPrefix(cleanRel, "../") || cleanRel == ".." {
		return "", fmt.Errorf("artifact path %q escapes workspace", rel)
	}
	full, err := workspace.ResolveInside(root, cleanRel)
	if err != nil {
		return "", err
	}
	rootPath, err := workspace.ResolveInside(root, filepath.ToSlash(filepath.Join("projects", s.Project, "sprints", s.Slug)))
	if err != nil {
		return "", err
	}
	if !inside(rootPath, full) {
		return "", fmt.Errorf("artifact path %q escapes sprint root", rel)
	}
	return full, nil
}

func inside(root, candidate string) bool {
	rel, err := filepath.Rel(filepath.Clean(root), filepath.Clean(candidate))
	if err != nil {
		return false
	}
	return rel == "." || (rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)))
}

package workspace

import (
	"fmt"
	"os"
	"path/filepath"
)

const MarkerFile = "ultraplan.yml"

type Root struct {
	Path string
}

type DiscoverOptions struct {
	ExplicitPath string
	EnvWorkspace string
	StartDir     string
}

func Discover(opts DiscoverOptions) (Root, error) {
	if opts.ExplicitPath != "" {
		return requireWorkspace(opts.ExplicitPath)
	}
	if opts.EnvWorkspace != "" {
		return requireWorkspace(opts.EnvWorkspace)
	}
	start := opts.StartDir
	if start == "" {
		var err error
		start, err = os.Getwd()
		if err != nil {
			return Root{}, fmt.Errorf("get working directory: %w", err)
		}
	}
	start, err := normalize(start)
	if err != nil {
		return Root{}, err
	}
	for {
		if HasMarker(start) {
			return Root{Path: start}, nil
		}
		parent := filepath.Dir(start)
		if parent == start {
			break
		}
		start = parent
	}
	return Root{}, fmt.Errorf("workspace not found: initialize one with 'ultraplan init-workspace'")
}

func requireWorkspace(path string) (Root, error) {
	root, err := normalize(path)
	if err != nil {
		return Root{}, err
	}
	if !HasMarker(root) {
		return Root{}, fmt.Errorf("invalid workspace %q: missing %s", root, MarkerFile)
	}
	return Root{Path: root}, nil
}

func HasMarker(root string) bool {
	info, err := os.Stat(filepath.Join(root, MarkerFile))
	return err == nil && !info.IsDir()
}

func normalize(path string) (string, error) {
	if path == "" {
		return "", fmt.Errorf("path is required")
	}
	abs, err := filepath.Abs(path)
	if err != nil {
		return "", fmt.Errorf("normalize path %q: %w", path, err)
	}
	return filepath.Clean(abs), nil
}

