type probeHeader struct {
	Revision int `json:"revision"`
}

// TestLoadTornRead probes whether Load can observe a header and item set from
// two different committed saves. The writer alternates between revision 1
// (items {a}) and revision 2 (items {a,b}). A consistent reader must never see
// revision 1 together with item b, nor revision 2 without item b.
func TestLoadTornRead(t *testing.T) {
	root := t.TempDir()
	store, err := Ensure(root)
	if err != nil {
		t.Fatal(err)
	}
	ctx := context.Background()

	h1, _ := json.Marshal(probeHeader{Revision: 1})
	h2, _ := json.Marshal(probeHeader{Revision: 2})
	rec1 := Record{Kind: "probe", Scope: "s", SchemaVersion: 1, Header: h1,
		Items: []Item{{Key: "a", Ordinal: 0, Payload: []byte(`{"k":"a"}`)}}}
	rec2 := Record{Kind: "probe", Scope: "s", SchemaVersion: 1, Header: h2,
		Items: []Item{{Key: "a", Ordinal: 0, Payload: []byte(`{"k":"a"}`)},
			{Key: "b", Ordinal: 1, Payload: []byte(`{"k":"b"}`)}}}

	var stop atomic.Bool
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		for !stop.Load() {
			if err := store.Save(ctx, rec1); err != nil {
				t.Errorf("save rec1: %v", err)
				return
			}
			if err := store.Save(ctx, rec2); err != nil {
				t.Errorf("save rec2: %v", err)
				return
			}
		}
	}()

	deadline := time.Now().Add(15 * time.Second)
	iterations := 0
	for time.Now().Before(deadline) {
		iterations++
		record, err := store.Load(ctx, "probe", "s")
		if err != nil {
			stop.Store(true)
			wg.Wait()
			t.Fatalf("load: %v", err)
		}
		var header probeHeader
		if err := json.Unmarshal(record.Header, &header); err != nil {
			stop.Store(true)
			wg.Wait()
			t.Fatalf("header: %v", err)
		}
		hasB := false
		for _, item := range record.Items {
			if item.Key == "b" {
				hasB = true
			}
		}
		if header.Revision == 1 && hasB {
			stop.Store(true)
			wg.Wait()
			t.Fatalf("TORN READ after %d iterations: header revision 1 observed with item b present (header=%s items=%d)", iterations, record.Header, len(record.Items))
		}
		if header.Revision == 2 && !hasB {
			stop.Store(true)
			wg.Wait()
			t.Fatalf("TORN READ after %d iterations: header revision 2 observed with item b missing", iterations)
		}
	}
	stop.Store(true)
	wg.Wait()
	t.Logf("no tear observed in %d iterations (window may be too narrow on this machine)", iterations)
}
