package sprint

import (
	"os"
	"path/filepath"
	"testing"
	"time"
)

// TestMigrateShadowsConcurrentFileWrite reproduces the lost-update interleaving
// between `storage migrate` and a live writer whose save began before the
// import committed:
//
//	migrate: LoadFlowState -> reads file content X (no row yet)
//	writer:  FlowStateInDatabase=false (probe) -> writes newer Y to FILE only
//	migrate: MigrateFlowStateToDatabase(X) -> row now exists with stale X
//
// From then on every load returns the stale X while the newest committed
// product state Y lives only in the shadowed checkpoint file.
func TestMigrateShadowsConcurrentFileWrite(t *testing.T) {
	root := t.TempDir()
	sp := Sprint{Project: "proj", Slug: "sp", Path: filepath.Join(root, "projects", "proj", "sprints", "sp")}

	stages := func(reqStatus StageStatus) []StageState {
		out := make([]StageState, 0, 7)
		for _, stage := range PlanningStages() {
			status := StatusMissing
			if stage == StageRequirements {
				status = reqStatus
			}
			out = append(out, StageState{Stage: stage, Status: status, Path: ArtifactRelPath(sp, stage)})
		}
		return out
	}

	prior := NewFlowState(sp, stages(StatusMissing), time.Now().UTC())
	if err := os.MkdirAll(filepath.Dir(FlowStateRelPathMust(root, sp)), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := saveFlowStateWithHooks(root, sp, prior, atomicWriteHooks{}); err != nil {
		t.Fatalf("seed flow state: %v", err)
	}

	// migrate reads the current file content.
	captured, err := LoadFlowState(root, sp)
	if err != nil {
		t.Fatalf("migrate read: %v", err)
	}

	// live writer commits a newer state to the file only; its authority probe
	// returned false because no row existed when it checked.
	newer := NewFlowState(sp, stages(StatusComplete), time.Now().UTC())
	if err := saveFlowStateWithHooks(root, sp, newer, atomicWriteHooks{}); err != nil {
		t.Fatalf("writer commit: %v", err)
	}

	// migrate imports the stale snapshot it captured earlier.
	if err := MigrateFlowStateToDatabase(root, sp, captured); err != nil {
		t.Fatalf("import: %v", err)
	}

	loaded, err := LoadFlowState(root, sp)
	if err != nil {
		t.Fatalf("load after import: %v", err)
	}
	if loaded.Stages[0].Status != StatusMissing {
		t.Fatalf("expected stale DB row to win (requirements=%s), got requirements=%s", StatusMissing, loaded.Stages[0].Status)
	}

	fileContent, err := os.ReadFile(FlowStateRelPathMust(root, sp))
	if err != nil {
		t.Fatal(err)
	}
	if len(fileContent) == 0 {
		t.Fatal("checkpoint file missing")
	}
	t.Logf("DB-authoritative state: requirements=%s (stale); file checkpoint holds requirements=complete but is never consulted again", loaded.Stages[0].Status)

	// The next writer save would heal this; the defect window is a crash or
	// quiet period before that next save. Show the healing for completeness.
	if err := SaveFlowState(root, sp, newer); err != nil {
		t.Fatalf("next writer save: %v", err)
	}
	healed, err := LoadFlowState(root, sp)
	if err != nil {
		t.Fatal(err)
	}
	if healed.Stages[0].Status != StatusComplete {
		t.Fatalf("expected healing on next save, got %s", healed.Stages[0].Status)
	}
}

func FlowStateRelPathMust(root string, s Sprint) string {
	path, err := FlowStatePath(root, s)
	if err != nil {
		panic(err)
	}
	return path
}
EOF
